#include <cuda_runtime.h>
#include <cstdio>
#include <vector>
#include <fstream>
#include <string>
#include <chrono>
#include <stdexcept>
#include <unistd.h>
#define main archived_memcpy_main
#include "../memcpy-cuda/main.cu"
#undef main
const int G=16,R=20;const int GUARD=(int)0xa5a55a5aU,POISON=0x13579bdf;
void check(cudaError_t e){if(e!=cudaSuccess)throw std::runtime_error(cudaGetErrorString(e));}
struct Case{int*host,*dev;std::vector<int>payload,initial;size_t n,sz;};
int main(){std::vector<int>pattern(1<<19);std::ifstream f("/home/imo/HeCBench_julia/src/memcpy-julia/pattern_u32.bin",std::ios::binary);f.read((char*)pattern.data(),pattern.size()*4);if(!f)throw std::runtime_error("fixture read");std::vector<Case>cases;std::vector<int>prefix;size_t sizes[16];setup(sizes);for(int mode=0;mode<2;mode++)for(int s=0;s<16;s++){Case a;a.sz=sizes[s];a.n=a.sz/4;a.payload.assign(a.n,1);if(mode)std::copy(pattern.begin(),pattern.begin()+a.n,a.payload.begin());a.initial.assign(a.n+2*G,GUARD);std::fill(a.initial.begin()+G,a.initial.begin()+G+a.n,POISON);a.host=(int*)malloc((a.n+2*G)*4);if(!a.host)throw std::runtime_error("host malloc");std::fill(a.host,a.host+a.n+2*G,GUARD);std::copy(a.payload.begin(),a.payload.end(),a.host+G);check(cudaMalloc(&a.dev,(a.n+2*G)*4));check(cudaMemcpy(a.dev,a.initial.data(),(a.n+2*G)*4,cudaMemcpyHostToDevice));prefix.insert(prefix.end(),a.host,a.host+a.n+2*G);prefix.insert(prefix.end(),a.initial.begin(),a.initial.end());prefix.insert(prefix.end(),a.initial.begin(),a.initial.end());cases.push_back(a);}for(auto&a:cases){check(cudaMemcpyAsync(a.dev+G,a.host+G,a.sz,cudaMemcpyHostToDevice,0));check(cudaDeviceSynchronize());check(cudaMemcpyAsync(a.host+G,a.dev+G,a.sz,cudaMemcpyDeviceToHost,0));check(cudaDeviceSynchronize());}for(int trial=1;trial<=5;trial++){std::vector<int>out;std::vector<double>dt;bool ok=true;for(auto&a:cases){std::copy(a.payload.begin(),a.payload.end(),a.host+G);check(cudaMemcpy(a.dev,a.initial.data(),(a.n+2*G)*4,cudaMemcpyHostToDevice));check(cudaDeviceSynchronize());auto start=std::chrono::steady_clock::now();for(int r=0;r<R;r++)check(cudaMemcpyAsync(a.dev+G,a.host+G,a.sz,cudaMemcpyHostToDevice,0));check(cudaDeviceSynchronize());dt.push_back(std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/R);std::vector<int>v(a.n+2*G);check(cudaMemcpy(v.data(),a.dev,v.size()*4,cudaMemcpyDeviceToHost));for(size_t i=0;i<v.size();i++){int expected=i>=G&&i<G+a.n?a.payload[i-G]:GUARD;ok&=v[i]==expected&&a.host[i]==expected;}out.insert(out.end(),v.begin(),v.end());std::copy(a.initial.begin(),a.initial.end(),a.host);check(cudaDeviceSynchronize());start=std::chrono::steady_clock::now();for(int r=0;r<R;r++)check(cudaMemcpyAsync(a.host+G,a.dev+G,a.sz,cudaMemcpyDeviceToHost,0));check(cudaDeviceSynchronize());dt.push_back(std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/R);for(size_t i=0;i<v.size();i++)ok&=a.host[i]==v[i];out.insert(out.end(),a.host,a.host+v.size());std::vector<int>again(v.size());check(cudaMemcpy(again.data(),a.dev,again.size()*4,cudaMemcpyDeviceToHost));ok&=again==v;out.insert(out.end(),again.begin(),again.end());}double sum=0;for(double t:dt)sum+=t;std::string path="/tmp/memcpy_"+std::to_string(getpid())+"_"+std::to_string(trial)+".bin";std::ofstream fout(path,std::ios::binary);fout.write((char*)prefix.data(),prefix.size()*4);fout.write((char*)out.data(),out.size()*4);fout.close();printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":%s,\"max_abs_error\":null,\"max_rel_error\":null,\"exact_word_mismatches\":%d,\"jit_excluded\":true,\"timing_region\":\"sum_32_cases_two_pageable_transfer_batches_plus_device_completion_per_repeat\",\"internal_repeats\":20,\"component_time_seconds\":[",trial,sum,ok?"true":"false",ok?0:-1);for(int i=0;i<(int)dt.size();i++)printf("%s%.12g",i?",":"",dt[i]);printf("],\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"int32\",\"count\":%zu,\"shape\":[%zu],\"byte_order\":\"little\"}}\n",path.c_str(),prefix.size()+out.size(),prefix.size()+out.size());}for(auto&a:cases){check(cudaFree(a.dev));free(a.host);}}
